#!/usr/bin/env python3
"""python3 make_tables.py -> RESULTS.md. Reads only data/*.tsv (NA stays NA); every number in the tables comes from there (the one-line captions are written by hand in this script)."""
import csv, os
D = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'data')
def tsv(n): return list(csv.DictReader((l for l in open(f'{D}/{n}.tsv') if not l.startswith('#')), delimiter='\t'))
def table(head, rows): return '| ' + ' | '.join(head) + ' |\n|' + '---|' * len(head) + '\n' + '\n'.join('| ' + ' | '.join(map(str, r)) + ' |' for r in rows) + '\n'
R = tsv('runs'); f = lambda x: x if x not in ('', 'NA') else 'n/m'
out = ['# Results (generated by make_tables.py from data/*.tsv; n/m = not measured yet)\n', 'Box: 4 cores (Intel Xeon 2.10 GHz, 1 thread per core), 15 GB RAM, hg38. Details: README.md.\n']
B = {}
def add(title, line, tab): B[title] = f'## {title}\n\n{line}\n\n{tab}'
runs = lambda e: [r for r in R if r['experiment'] == e]
n = lambda x: float(x)
def one(e, data, tool, col, **kw): return next(n(r[col]) for r in R if r['experiment'] == e and r['data'] == data and r['tool'] == tool and r['commit'] != 'f973b77' and all(r[k] == v for k, v in kw.items()))
cols = ['experiment', 'data', 'pairs', 'tool', 'commit', 'wall s', 'map s', 'CPU s', 'peak GB', 'Gbp/hr', 'Gbp/core-hr', 'runs']
row = lambda r: [r['experiment'], r['data'], r['pairs'], r['tool'], r['commit'], f(r['wall_s']), f(r['map_s']), f(r['cpu_s']), f(r['peak_GB']), f(r['Gbp_hr']), f(r['Gbp_core_hr']), r['reps']]
RP = tsv('reps'); import statistics as st
vcols = ['experiment', 'data', 'pairs', 'tool', 'commit', 'run', 'wall s', 'CPU s', 'peak GB', 'Gbp/hr', 'Gbp/core-hr']
vrow = lambda r: [r['experiment'], r['data'], r['pairs'], r['tool'], r['commit'], r['rep'], f(r['wall_s']), f(r['cpu_s']), f(r['peak_GB']), f(r['Gbp_hr']), f(r['Gbp_core_hr'])]
groups = sorted({(r['experiment'], r['data'], r['tool']) for r in RP}, key=lambda k: (k[0], k[1], k[2] != 'lean-align'))
def stat(k, col):
    v = sorted(float(r[col]) for r in RP if (r['experiment'], r['data'], r['tool']) == k and r[col] not in ('', 'NA'))
    return (f'{st.median(v):.1f} ({v[0]:.1f} to {v[-1]:.1f})' if len(v) > 1 else f'{v[0]:.1f}') if v else 'n/m'
add('lean-align against minibwa: medians', 'The headline comparison (figs/vs_minibwa.svg). Median of the runs, with min to max in brackets; n = number of runs. Four threads on four cores, lean-align (builds in the commit column of the per-run table) against minibwa c07de5c. gz5m = 5M pairs from gz files, the newest session (lean-align cc26db2 and minibwa; gz5m_prev_build = f465a57 runs of the same session; gz5m_old_session = the earlier session, not plotted); stream = the first 10M NovaSeq pairs streamed from the network, same pipeline for both tools, 3 runs each; stream_single = older single streamed runs (other sizes, and the HiSeq lane, which figs/vs_minibwa plots for HiSeq until HiSeq repetitions exist).', table(['experiment', 'data', 'tool', 'n', 'Gbp/hr', 'Gbp/core-hr', 'peak GB'], [[k[0], k[1], k[2], sum((r['experiment'], r['data'], r['tool']) == k for r in RP), stat(k, 'Gbp_hr'), stat(k, 'Gbp_core_hr'), stat(k, 'peak_GB')] for k in groups]))
add('lean-align against minibwa: every single run', 'One row per run, as in data/reps.tsv. The older minibwa NovaSeq 10M single run is not here because its wall time includes a cold index load of 158.9 s (it is in the streamed table below). CPU of the stream rows is the aligner only; for gz5m it includes both gzips.', table(vcols, [vrow(r) for r in RP]))
add('Speed at 4 threads, 5M pairs from gz files', 'Two methods. gz5m (before and after bars): map time, index load excluded. gz5m_script (lean-align against minibwa): the same script, Testing/ec2/run.sh, for both tools; wall includes index load and CPU includes both gzips. Do not mix the two methods in one bar chart.', table(cols, [row(r) for r in runs('gz5m') + runs('gz5m_script')]))
add('Large streamed runs (from the network, no disk)', 'After the fix throughput is flat from 10M to 40M pairs, before it falls with run size, and minibwa is flat from 20M to 40M. The minibwa 10M wall includes a cold index load of 158.9 s. Peak memory: lean-align 5.7 GB (the index is 5.3 GB), minibwa 8.8 GB. Per-run files are in Testing/results/stream/.', table(cols, [row(r) for r in runs('stream')]))
hb, ha = one('lane', 'hiseq_2x250', 'lean-align-before', 'map_s'), one('lane', 'hiseq_2x250', 'lean-align', 'map_s'); nb = one('lane', 'novaseq_2x151', 'lean-align-before', 'map_s'); na = sorted(n(r['map_s']) for r in runs('lane') if r['data'] == 'novaseq_2x151' and r['tool'] == 'lean-align')
mh = one('lane', 'hiseq_2x250', 'minibwa', 'map_s')
add('Whole lanes (HiSeq 33.9M pairs, NovaSeq 40M pairs)', f'The slow-pair fix cuts the map time by {100 * (1 - ha / hb):.0f} percent on the HiSeq lane and by {100 * (1 - na[-1] / nb):.0f} to {100 * (1 - na[0] / nb):.0f} percent on NovaSeq. On the HiSeq lane minibwa needs {mh / ha:.1f} times as long as lean-align f465a57 (map seconds). minibwa on NovaSeq 40M is the 40M row of the streamed table above (same data, different box and downloader).', table(cols, [row(r) for r in runs('lane')]))
J = tsv('slow_jobs')
add('Slow jobs', f"Before the fix, jobs of up to {max(n(r['job_max_s']) for r in J if r['build'] == 'before'):.0f} s left fewer than 4 cores busy for {min(n(r['pct_wall_under_4_jobs']) for r in J if r['build'] == 'before'):.0f} to {max(n(r['pct_wall_under_4_jobs']) for r in J if r['build'] == 'before'):.0f} percent of the run. After it, the longest job is {max(n(r['job_max_s']) for r in J if r['build'] == 'after'):.1f} s.", table(['data', 'build', 'jobs over 5 s', 'longest job s', '% of wall with fewer than 4 jobs running', 'wall over ideal s', 'core use incl. gunzip'], [[r[k] for k in ('data', 'build', 'jobs_over_5s', 'job_max_s', 'pct_wall_under_4_jobs', 'wall_over_ideal_s', 'core_use_pipeline')] for r in J]))
P = tsv('slow_pairs')
add('Slow pairs, mapped alone on 1 core (seconds)', 'The slowest single pairs, before and after. The SAM lines are identical in all three builds.', table(['pair', '64ae73f', '351301d', 'f465a57'], [[r['pair'], f(r['before_64ae73f']), f(r['fix1_351301d']), f(r['merged_f465a57'])] for r in P]))
S = tsv('slow_pairs_stream'); n1 = sum(float(r['before_ms']) >= 1000 for r in S); mx = max(float(r['after_ms']) for r in S)
add('Slow pairs inside the HiSeq lane run', f'{len(S)} pairs took one second or more before; the same pairs after the fix take at most {mx:.0f} ms. Classes: ' + ', '.join(f'{c} {sum(r["class"] == c for r in S)}' for c in sorted({r['class'] for r in S})) + '.', table(['pair', 'before ms', 'after ms', 'trimmed length mate 1/2', 'class'], [[r['pair'], r['before_ms'], r['after_ms'], f"{r['len1']}/{r['len2']}", r['class']] for r in S[:12]]) + f'\n(12 of {len(S)} rows shown; all rows in data/slow_pairs_stream.tsv.)\n')
E = tsv('ec2_compare'); ev = lambda ds, m, t: next(r['value'] for r in E if r['dataset'] == ds and r['metric'] == m and r['tool'] == t)
sp = lambda ds, m: next(r for r in E if r['dataset'] == ds and r['metric'] == m)
add('Real reads, 1M pairs each: lean-align f465a57 against minibwa (Testing/ec2/compare.py)', 'Mapped and unique pairs (% of 1M pairs), and how often the two tools agree where both give an answer. "Unique" = our XU:Z:unique, minibwa MAPQ 60 on both mates. Same place = same chromosome and strand, overlapping alignment.', table(['dataset', 'mapped: lean-align', 'mapped: minibwa', 'unique: lean-align', 'unique: minibwa MAPQ 60', 'ours unique and minibwa mapped: same place', 'ours unique and minibwa MAPQ 60: same place'], [[ds, ev(ds, 'pct_mapped', 'lean-align'), ev(ds, 'pct_mapped', 'minibwa'), ev(ds, 'pct_unique', 'lean-align'), ev(ds, 'pct_unique', 'minibwa')] + [f"{int(sp(ds, m)['n_same']):,} of {int(sp(ds, m)['n']):,}" for m in ('same_place_ours_unique_and_minibwa_mapped', 'same_place_ours_unique_and_minibwa_mapq60')] for ds in ('novaseq_2x151', 'hiseq_2x250')]))
A = tsv('accuracy'); g = lambda **k: next((r['value'] for r in A if all(r[a] == b for a, b in k.items())), 'n/m')
add('Real reads, 200k pairs: proper and unique pairs against minibwa (% of all pairs)', 'The older 200k-pair measurement, on lean-align 027ef1e (the real-read part was not re-run on f465a57). "Unique" is our XU:Z:unique against minibwa MAPQ 60 on both mates.', table(['dataset', 'proper: lean-align', 'proper: minibwa', 'unique: lean-align', 'unique: minibwa'], [[ds, g(block='real', dataset=ds, metric='pct_proper_pair', tool='lean-align'), g(block='real', dataset=ds, metric='pct_proper_pair', tool='minibwa'), g(block='real', dataset=ds, metric='pct_unique', tool='lean-align'), g(block='real', dataset=ds, metric='pct_unique', tool='minibwa')] for ds in ('novaseq_200k', 'hiseq_200k')]))
rows = [[m, r['class'], r['n_pairs'], g(block='sim', dataset=m, **{'class': r['class']}, metric='pct_pair_correct', tool='lean-align'), g(block='sim', dataset=m, **{'class': r['class']}, metric='pct_pair_correct', tool='minibwa')] for m in ('mason', 'low', 'high') for r in A if r['block'] == 'sim' and r['dataset'] == m and r['tool'] == 'lean-align']
add('Simulated reads: pairs placed correctly (%), by our class', 'Re-measured on f465a57; every value is identical to the 027ef1e measurement. Pairs we call unique are as correct as minibwa. Pairs we leave unknown or not proper are not placed, so they count as wrong for us.', table(['simulation', 'our class', 'pairs', 'lean-align', 'minibwa'], rows))
TR = tsv('this_round')
def mdn(e, ds, col):
    v = sorted(float(r[col]) for r in RP if r['experiment'] == e and r['data'] == ds and r['tool'] == 'lean-align' and r[col] not in ('', 'NA'))
    return st.median(v) if v else None
rows = []
for ds in ('novaseq_2x151', 'hiseq_2x250'):
    for lab, col in (('wall s', 'wall_s'), ('CPU s (incl. gzips)', 'cpu_s'), ('Gbp/hr', 'Gbp_hr'), ('Gbp/core-hr', 'Gbp_core_hr')):
        a, b = mdn('gz5m_prev_build', ds, col), mdn('gz5m', ds, col)
        if a and b: rows.append([ds, lab, f'{a:.2f}', f'{b:.2f}', f'{100 * (b / a - 1):+.1f}%'])
    for r in TR:
        if r['data'] == ds: rows.append([ds, r['metric'] + ' (callgrind, 50k pairs)', 'n/m', 'n/m', f"{float(r['change_pct']):+.1f}%"])
def meanv(e, ds, col):
    v = [float(r[col]) for r in RP if r['experiment'] == e and r['data'] == ds and r['tool'] == 'lean-align' and r[col] not in ('', 'NA')]
    return sum(v) / len(v) if v else None
for ds in ('novaseq_2x151', 'hiseq_2x250'):
    for lab, col in (('streamed wall s (mean)', 'wall_s'), ('streamed aligner CPU s (mean)', 'cpu_s'), ('streamed Gbp/hr (mean)', 'Gbp_hr'), ('streamed Gbp/core-hr (mean)', 'Gbp_core_hr')):
        a, b = meanv('stream_prev_build', ds, col), meanv('stream', ds, col)
        if a and b: rows.append([ds, lab, f'{a:.2f}', f'{b:.2f}', f'{100 * (b / a - 1):+.1f}%'])
if rows: add('This round: lean-align new build against the previous build (same session)', 'Medians of the 3 alternating runs of the same session (5M gz pairs, 4 threads), means for the streamed rows (previous build: 2 runs, new build: 3 runs, first 10M pairs, one container, slower than the night before, so compare within the session only), plus the callgrind instruction change. The figure is figs/this_round.svg. Negative wall, CPU and instruction changes are improvements.', table(['data', 'metric', 'previous build (f465a57)', 'new build', 'change'], rows))
order = [('lean-align against minibwa', ['lean-align against minibwa: medians', 'lean-align against minibwa: every single run']),
         ('Streamed runs, whole lanes and accuracy', ['Large streamed runs (from the network, no disk)', 'Whole lanes (HiSeq 33.9M pairs, NovaSeq 40M pairs)', 'Real reads, 1M pairs each: lean-align f465a57 against minibwa (Testing/ec2/compare.py)', 'Real reads, 200k pairs: proper and unique pairs against minibwa (% of all pairs)', 'Simulated reads: pairs placed correctly (%), by our class']),
         ('How it got faster (before and after)', ['This round: lean-align new build against the previous build (same session)'] * (1 if rows else 0) + ['Speed at 4 threads, 5M pairs from gz files', 'Slow jobs', 'Slow pairs, mapped alone on 1 core (seconds)', 'Slow pairs inside the HiSeq lane run'])]
assert sorted(sum((k for _, k in order), [])) == sorted(B), sorted(set(B) ^ set(sum((k for _, k in order), [])))
IMG = '![lean-align against minibwa: speed](figs/vs_minibwa.png)\n\n![lean-align against minibwa: peak memory](figs/vs_minibwa_memory.png)\n\nBar = median, whisker = min to max, dots = single runs, 4 threads, n = number of runs (see the tables below).\n'
for i, (h, keys) in enumerate(order): out.append(f'# {h}\n'); out += ([IMG] if i == 0 else []) + [B[k] for k in keys]
open(os.path.join(D, '..', 'RESULTS.md'), 'w').write('\n'.join(out))
